svg.script:
//
  (function() {
    function init() {
      var aud = document.getElementById('aud');
      if (!aud) { setTimeout(init, 100); return; }

      // JS is available: unify all browsers on the SMIL onclick layer.
      // Hide autoplay (ESR fallback) and CSS layer (Nightly fallback).
      var layerAutoplay = document.querySelector('.smil-autoplay');
      var layerCss      = document.querySelector('.css-layer');
      var layerOnclick  = document.querySelector('.smil-onclick');
      if (layerAutoplay) layerAutoplay.style.display = 'none';
      if (layerCss)      layerCss.style.display      = 'none';
      if (layerOnclick)  layerOnclick.style.display   = 'block';

      // Show controls, hide all no-JS fallback messages
      var els = {
        msgEsr:     '.msg-esr',
        msgNoPause: '.msg-no-pause',
        msgAnimLbl: '.msg-anim-label',
        buttonsRow: '.buttons-row',
        msgNightlyBelow: '.msg-nightly-below',
        resetBtn:   '#resetBtn',
      };
      document.querySelector(els.msgEsr)     && (document.querySelector(els.msgEsr).style.display     = 'none');
      document.querySelector(els.msgNoPause) && (document.querySelector(els.msgNoPause).style.display  = 'none');
      document.querySelector(els.msgAnimLbl) && (document.querySelector(els.msgAnimLbl).style.display  = 'block');
      document.querySelector(els.buttonsRow) && (document.querySelector(els.buttonsRow).style.display  = 'block');
      // CLEAR button and its note are no longer needed — hash is never set via JS path
      document.querySelector(els.msgNightlyBelow) && (document.querySelector(els.msgNightlyBelow).style.display = 'none');
      document.querySelector(els.resetBtn)        && (document.querySelector(els.resetBtn).parentNode.style.display = 'none');

      var anim = document.querySelector('.smil-onclick animateMotion');

      function clearHash() {
        if (location.hash) history.replaceState(null, '', location.pathname);
      }

      // Audio play/pause → drive SMIL directly, hash never involved
      aud.addEventListener('play',  function() { if (anim) anim.beginElement(); });
      aud.addEventListener('pause', function() { if (anim) anim.endElement();   });

      // Button clicks — prevent <a> hash navigation, drive SMIL directly
      function interceptA(id, fn) {
        var btn = document.getElementById(id);
        if (!btn) return;
        btn.parentNode.addEventListener('click', function(e) {
          e.preventDefault();
          fn();
        });
      }

      interceptA('startBtn', function() { if (anim) anim.beginElement(); });
      interceptA('stopBtn',  function() { if (anim) anim.endElement();   });
      // resetBtn is hidden but intercept anyway as safety
      interceptA('resetBtn', function() { clearHash(); });
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', init);
    } else {
      init();
    }
  })();
  //
